"""QR tokens: random codes, created from events, revoked and regenerated by administrators."""

from __future__ import annotations

import secrets

from sqlalchemy.orm import Session

from core import audit
from core.database import utcnow
from core.deps import CurrentOfficer
from core.errors import ConflictError, ForbiddenError, NotFoundError, ValidationAppError
from module_7.models import ACTIVE, REVOKED, TYPE_BALE, TYPE_HEAP, QrToken
from module_7.repository import TokenRepository
from module_7.services import cache

#: RFC 4648 base32 alphabet: upper-case letters and 2 to 7, no look-alike 0, 1, 8 or 9.
ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567"
LENGTH = 12  # 60 bits of randomness


def new_token() -> str:
    """12 characters from the operating system's secure random source."""
    return "".join(secrets.choice(ALPHABET) for _ in range(LENGTH))


def looks_like_token(text: str) -> bool:
    return len(text) == LENGTH and all(c in ALPHABET for c in text)


def require_admin(officer: CurrentOfficer) -> None:
    """The only role check in Module 7: revoking and regenerating are for administrators."""
    if not officer.sees_all:
        raise ForbiddenError(
            "Only an administrator can revoke or regenerate a code.", code="qr_admin_only"
        )


def _reason(raw: str | None) -> str:
    value = (raw or "").strip()
    if not value:
        raise ValidationAppError("Give a reason.", code="qr_reason_required")
    if len(value) > 500:
        raise ValidationAppError("The reason is too long.", code="qr_reason_too_long")
    return value


class TokenService:
    def __init__(self, session: Session) -> None:
        self.session = session
        self.repo = TokenRepository(session)

    def _unique(self) -> str:
        for _ in range(10):
            token = new_token()
            if not self.repo.exists(token):
                return token
        raise RuntimeError("Could not draw a unique token")  # pragma: no cover - 2**60 space

    def ensure_bale_token(
        self, serial: str, heap_id: str, *, officer_id: str | None = None
    ) -> QrToken:
        """Idempotent: an active token for the bale is returned as it is."""
        existing = self.repo.active_for_bale(serial)
        if existing is not None:
            return existing
        token = QrToken(
            token=self._unique(),
            token_type=TYPE_BALE,
            bale_serial=serial,
            heap_id=heap_id,
            status=ACTIVE,
            created_by=officer_id,
            created_at=utcnow(),
        )
        self.repo.add(token)
        self.session.flush()
        return token

    def ensure_heap_token(self, heap_id: str, *, officer_id: str | None = None) -> QrToken:
        existing = self.repo.active_for_heap(heap_id)
        if existing is not None:
            return existing
        token = QrToken(
            token=self._unique(),
            token_type=TYPE_HEAP,
            bale_serial=None,
            heap_id=heap_id,
            status=ACTIVE,
            created_by=officer_id,
            created_at=utcnow(),
        )
        self.repo.add(token)
        self.session.flush()
        return token

    def _revoke(self, token: QrToken, reason: str, officer_id: str | None) -> None:
        token.status = REVOKED
        token.revoked_by, token.revoked_at, token.revoke_reason = officer_id, utcnow(), reason
        audit.record(
            "qr_token",
            token.id,
            "revoke",
            officer_id,
            {
                "token_type": token.token_type,
                "bale_serial": token.bale_serial,
                "heap_id": token.heap_id,
                "reason": reason,
            },
            session=self.session,
        )
        cache.invalidate()

    def revoke_for_bale(self, serial: str, reason: str, officer_id: str | None) -> QrToken | None:
        """Used when a bale is voided: its code stops working at once."""
        token = self.repo.active_for_bale(serial)
        if token is not None:
            self._revoke(token, reason, officer_id)
        return token

    def revoke(self, token_text: str, officer: CurrentOfficer, reason: str | None) -> QrToken:
        require_admin(officer)
        reason = _reason(reason)
        token = self.repo.by_token(token_text)
        if token is None:
            raise NotFoundError("That code does not exist.", code="qr_token_not_found")
        if token.status != ACTIVE:
            raise ConflictError("That code is already revoked.", code="qr_token_revoked")
        self._revoke(token, reason, officer.id)
        self.session.commit()
        return token

    def regenerate(
        self,
        serial: str,
        officer: CurrentOfficer,
        reason: str | None,
        *,
        bale_active: bool,
        heap_id: str,
    ) -> QrToken:
        """Revoke the bale's current code and issue a new one. Only for an active bale."""
        require_admin(officer)
        reason = _reason(reason)
        if not bale_active:
            raise ConflictError("Only an active bale gets a code.", code="qr_bale_not_active")
        old = self.repo.active_for_bale(serial)
        if old is not None:
            self._revoke(old, f"Regenerated: {reason}", officer.id)
            self.session.flush()
        new = self.ensure_bale_token(serial, heap_id, officer_id=officer.id)
        audit.record(
            "qr_token",
            new.id,
            "regenerate",
            officer.id,
            {"bale_serial": serial, "previous_token_id": old.id if old else None, "reason": reason},
            session=self.session,
        )
        self.session.commit()
        return new
